//! The two generated files: the scheme JSON (one class per line, so a
//! rebuild diffs line by line) and SOURCES.md.

use std::fmt::Write;

use shelfmark_core::scheme::SchemeDoc;

use crate::build::Stats;
use crate::sources::{Lock, LICENSE_URLS, REPO};

/// The scheme as JSON: header fields pretty-printed, then one class per
/// line.
pub fn scheme_json(doc: &SchemeDoc) -> Result<String, String> {
    let err = |e: serde_json::Error| e.to_string();
    let mut head = doc.clone();
    head.classes.clear();
    let head = serde_json::to_string_pretty(&head).map_err(err)?;
    let head = head
        .trim_end()
        .strip_suffix('}')
        .and_then(|h| h.trim_end().strip_suffix("\"classes\": []"))
        .ok_or("unexpected scheme JSON layout")?;
    let mut out = format!("{head}\"classes\": [\n");
    for (i, c) in doc.classes.iter().enumerate() {
        let sep = if i + 1 < doc.classes.len() { "," } else { "" };
        let _ = writeln!(out, "    {}{sep}", serde_json::to_string(c).map_err(err)?);
    }
    out.push_str("  ]\n}\n");
    Ok(out)
}

fn list(items: &[String]) -> String {
    if items.is_empty() {
        "none".to_string()
    } else {
        items.join("; ")
    }
}

/// SOURCES.md: the lock entry, the license evidence and what the build did.
pub fn sources_md(lock: &Lock, s: &Stats, doc: &SchemeDoc) -> String {
    let mut o = String::new();
    let _ = write!(
        o,
        "# FDC scheme: sources\n\n\
         Generated by `schemes/fdc/builder` (`fdc-scheme build`); do not edit by hand.\n\
         `fdc.json` is scheme `{name}@{version}` with {n} classes and validates against\n\
         `schemas/scheme.schema.json` and `shelfmark_core::scheme::SchemeDoc`.\n\n\
         ## Rebuild\n\n\
         ```sh\n\
         cd schemes/fdc/builder\n\
         cargo run --release -- fetch --cache /tmp/fdc-sources   # network; rewrites sources.lock.json\n\
         cargo run --release -- build --cache /tmp/fdc-sources   # offline; deterministic from the lock\n\
         cargo run --release -- check --cache /tmp/fdc-sources   # fails if fdc.json or SOURCES.md is stale\n\
         ```\n\n\
         `build` refuses a cached file whose sha256 differs from `sources.lock.json`.\n\n\
         ## License\n\n\
         The Free Decimal Correspondence is dedicated to the public domain by its editor, John Mark\n\
         Ockerbloom, under CC0 1.0. The statement appears in the header of `fdc.txt` itself, in the\n\
         repository's `LICENSE` file (GitHub reports `CC0-1.0`) and on the FDC page. `fdc.json` may\n\
         therefore ship inside an open-source binary or package, and no attribution is required (it\n\
         is courteous: \"Free Decimal Correspondence, edited by John Mark Ockerbloom\").\n\
         No OCLC Dewey Decimal Classification data is used: FDC is compatible with Dewey numbers by\n\
         design but was written from the 1922 11th edition, which is out of copyright.\n\n\
         License evidence, fetched 2026-10-09:\n\n"
    ,
        name = doc.name,
        version = doc.version,
        n = doc.classes.len(),
    );
    for u in LICENSE_URLS {
        let _ = writeln!(o, "- <{u}>");
    }
    o.push_str(
        "\n## Source\n\n| file | commit | fetched | bytes | sha256 |\n|---|---|---|---|---|\n",
    );
    for l in &lock.sources {
        let _ = writeln!(
            o,
            "| [{}]({}) | `{}` | {} | {} | `{}` |",
            l.file, l.url, l.commit, l.fetched, l.bytes, l.sha256
        );
    }
    let _ = write!(
        o,
        "\nRepository: <{REPO}>. The commit is the last one that touched `fdc.txt` (2015-07-26).\n\n\
         ## What the build kept\n\n\
         - classes: {classes} ({ranges} ranges, {roots} hundreds-level roots)\n\
         - depth: {depth} levels (mean {mean_depth:.2}); classes per level: {levels}\n\
         - branching: max {max_branch} children (`{max_code}`), mean {mean_branch:.2} over the {internal} classes that have children\n\
         - vocabulary terms: {terms} ({lcsh} marked in the file as authorized LCSH headings, source `fdc-lcsh`; the rest source `fdc`)\n\
         - labels: the first alternative of each entry, its `+` subjects joined with `; `\n\
         - plain hundreds and tens classes carry their decimal span as a range (`010` is 010-019)\n\n\
         ## What the build changed\n\n\
         - upstream errors corrected: {errata}\n\
         - ranges widened to the end of a tens class: {widened}\n\
         - repeated numbers merged into one class (subjects joined as with `+`): {merged}\n",
        merged = list(&s.merged),
        classes = s.classes,
        ranges = s.ranges,
        roots = s.roots,
        depth = s.max_depth,
        mean_depth = s.mean_depth,
        levels = s
            .depth_counts
            .iter()
            .map(usize::to_string)
            .collect::<Vec<_>>()
            .join(", "),
        max_branch = s.max_branch,
        max_code = s.max_branch_code,
        mean_branch = s.mean_branch,
        internal = s.internal,
        terms = s.vocab_terms,
        lcsh = s.lcsh_terms,
        errata = list(&s.errata),
        widened = list(&s.widened),
    );
    o
}
